class MockAnalyticsService implements AnalyticsService {
  final List<AnalyticsEvent> _events = [];
  static const sensitiveKeys = {'phone','phoneNumber','mobile','address','otp','token','accessToken','refreshToken','document','documentData','coordinates','latitude','longitude'};
  @override Future<void> record(AnalyticsEvent event) async { final safe = <String,Object>{}; for (final entry in event.properties.entries) { if (!sensitiveKeys.contains(entry.key) && !sensitiveKeys.any((key) => entry.key.toLowerCase().contains(key.toLowerCase()))) safe[entry.key] = entry.value; } _events.add(AnalyticsEvent(type: event.type, occurredAt: event.occurredAt, properties: safe)); }
  @override Future<List<AnalyticsEvent>> events({AnalyticsTimeRange? range}) async { if (range == null || range == AnalyticsTimeRange.custom) return List.unmodifiable(_events); final days = switch(range) { AnalyticsTimeRange.today => 1, AnalyticsTimeRange.last7Days => 7, AnalyticsTimeRange.last30Days => 30, AnalyticsTimeRange.last90Days => 90, _ => 36500 }; final cutoff = DateTime.now().subtract(Duration(days: days)); return _events.where((e) => e.occurredAt.isAfter(cutoff)).toList(growable:false); }
  @override Future<void> clear() async => _events.clear();
}

